// Rewrites the math in a reply into the forms the desktop app draws itself.
// The Code tab draws a $$ block on lines of its own with KaTeX, and $...$
// and \(...\) where its tests (guards.ts) take them for math. It leaves as
// typed \[...\], an environment written without dollars, $$...$$ on one
// line or in a sentence, and an inline formula its tests refuse (one longer
// than 60 characters between dollars, a $ next to a character it stops at,
// a formula of short names such as F_G or Re); and KaTeX refuses \label and
// the amsmath environments it lacks. Pure functions, no engine calls, so
// they are easy to test.

import { backslashDraws, charBefore, dollarClosesBefore, dollarDraws, dollarOpensAfter, hasTexMarks, isPlain, MAX_BACKSLASH_BODY } from './guards'

// A message as the mod draws it when it holds figures: runs of markdown for
// the app's own renderer, and the ```tikz blocks between them.
export type Piece = { kind: 'md'; text: string } | { kind: 'figure'; source: string; raw: string }

// A code fence's opening or closing line, in a quote or a list too.
const FENCE_RE = /^((?:[ \t]*>)*)[ \t]*(```+|~~~+)[ \t]*([\w-]*)/

// The environments that are math with no dollars around them: amsmath's
// display environments and the ones that sit inside a formula.
const BARE_ENVS = new Set([
  'equation', 'align', 'flalign', 'alignat', 'gather', 'multline', 'eqnarray', 'split',
  'aligned', 'alignedat', 'gathered', 'cases', 'dcases', 'rcases', 'drcases',
  'matrix', 'pmatrix', 'bmatrix', 'Bmatrix', 'vmatrix', 'Vmatrix', 'smallmatrix', 'array', 'subarray', 'CD',
])

// What each display environment becomes inside a $$ block: forms KaTeX draws
// anywhere in a formula. A formula in a reply would number its rows from (1)
// each time, so the numbers go; equation leaves its content alone.
const ENV_REPLACEMENT: Record<string, string> = {
  equation: '',
  align: 'aligned',
  flalign: 'aligned',
  split: 'aligned',
  alignat: 'alignedat',
  gather: 'gathered',
  multline: 'gathered',
  eqnarray: 'array',
}

// A display formula longer than this is two stray delimiters far apart.
const MAX_DISPLAY_CHARS = 8000

// A mark only TeX makes. \[...\] is also how Markdown writes brackets, as
// in a citation \[1\]: one with none of these on one line is brackets when
// words share its line or it holds letters of another script.
const TEX_MARK = /[\\^_=+<>{}|]/

// Set beside a dollar the app would not open or close at, to stand between
// it and the character that stops it. It draws as nothing.
const ZERO_WIDTH_SPACE = '​'

// A name of one or two letters with at most a one-character subscript, as
// in F_G, Re, Re_D. The app's tests take a formula of names with no mark of
// TeX only when each is one letter and not a capital with a capital
// subscript.
const SHORT_NAME = /[A-Za-z]{1,2}(?:_[A-Za-z0-9])?/g

// A formula or code span, by where it starts and ends in the text. `open` is
// how a formula was written: $ or \( inline; \[, $$, or an environment's own
// \begin (empty) for display. `tex` is what lies between its delimiters; for
// an environment, the environment itself.
type Segment =
  | { kind: 'code'; start: number; end: number }
  | { kind: 'inline'; start: number; end: number; open: '$' | '\\('; tex: string }
  | { kind: 'display'; start: number; end: number; open: '\\[' | '$$' | ''; tex: string }

// The closing $ of an inline formula that opens just before `start`, or -1.
// The rules keep money as money: no space just inside either dollar, no
// digit straight after the closing one, and no line break inside. A $ inside
// braces belongs to the formula, as in \text{if $x>0$}.
function closeInline(text: string, start: number): number {
  const first = text[start]
  if (first === undefined || first === '$' || /\s/.test(first)) return -1
  const closes = (j: number) => !/\s/.test(text[j - 1] ?? ' ') && !/\d/.test(text[j + 1] ?? '')
  let depth = 0
  // With braces that never balance, as in $\frac{a$, the first $ closes.
  let inBraces = -1
  for (let j = start; j < text.length; j++) {
    const c = text[j]
    if (c === '\n') break
    if (c === '\\') j += 1
    else if (c === '{') depth += 1
    else if (c === '}') depth = Math.max(0, depth - 1)
    else if (c === '$') {
      if (depth === 0) return closes(j) ? j : -1
      if (inBraces < 0 && closes(j)) inBraces = j
    }
  }
  return inBraces
}

// The closing $$ of a display formula whose body starts at `start`, or -1.
function closeDisplay(text: string, start: number): number {
  let depth = 0
  let inBraces = -1
  const end = Math.min(text.length - 1, start + MAX_DISPLAY_CHARS)
  for (let j = start; j < end; j++) {
    const c = text[j]
    if (c === '\\') j += 1
    else if (c === '{') depth += 1
    else if (c === '}') depth = Math.max(0, depth - 1)
    else if (c === '$' && text[j + 1] === '$') {
      if (depth === 0) return j
      if (inBraces < 0) inBraces = j
      j += 1
    }
  }
  return inBraces
}

// The end of an environment whose body starts at `start`: just past the
// \end{name} that closes it, nested ones of the same name counted, or -1.
function closeEnv(text: string, start: number, name: string): number {
  const begin = `\\begin{${name}}`
  const end = `\\end{${name}}`
  const limit = Math.min(text.length, start + MAX_DISPLAY_CHARS)
  let depth = 1
  let j = start
  while (j < limit) {
    const b = text.indexOf(begin, j)
    const e = text.indexOf(end, j)
    if (e < 0 || e >= limit) return -1
    if (b >= 0 && b < e) {
      depth += 1
      j = b + begin.length
      continue
    }
    depth -= 1
    j = e + end.length
    if (depth === 0) return j
  }
  return -1
}

// The closing run of a code span opened by `ticks` backticks, or -1. A code
// span does not cross a blank line.
function closeCode(text: string, start: number, ticks: number): number {
  const blank = text.slice(start).search(/\n[ \t]*\n/)
  const limit = blank < 0 ? text.length : start + blank
  let j = start
  while (j < limit) {
    const k = text.indexOf('`', j)
    if (k < 0 || k >= limit) return -1
    let run = 1
    while (text[k + run] === '`') run += 1
    if (run === ticks) return k
    j = k + run
  }
  return -1
}

// Reads text left to right and marks its code spans and formulas. Reading in
// order is what keeps `$a$$b$` two inline formulas, a $$ inside a code span
// code, and an environment inside a formula part of that formula.
function scan(text: string): Segment[] {
  const out: Segment[] = []
  let i = 0
  while (i < text.length) {
    const c = text[i]
    if (c === '\\') {
      const next = text[i + 1]
      if (next === '(') {
        const close = text.indexOf('\\)', i + 2)
        // An inline formula never crosses a blank line.
        if (close > i + 2 && !/\n[ \t]*\n/.test(text.slice(i + 2, close))) {
          out.push({ kind: 'inline', start: i, end: close + 2, open: '\\(', tex: text.slice(i + 2, close) })
          i = close + 2
          continue
        }
      } else if (next === '[') {
        const close = text.indexOf('\\]', i + 2)
        if (close > i + 2 && close - i < MAX_DISPLAY_CHARS && text.slice(i + 2, close).trim()) {
          out.push({ kind: 'display', start: i, end: close + 2, open: '\\[', tex: text.slice(i + 2, close) })
          i = close + 2
          continue
        }
      } else if (next === 'b') {
        const m = /^\\begin\{([A-Za-z]+)(\*?)\}/.exec(text.slice(i, i + 32))
        if (m && BARE_ENVS.has(m[1] ?? '')) {
          const end = closeEnv(text, i + m[0].length, `${m[1]}${m[2]}`)
          if (end > 0) {
            out.push({ kind: 'display', start: i, end, open: '', tex: text.slice(i, end) })
            i = end
            continue
          }
        }
      }
      // Any other backslash escapes the next character: \$ is a dollar sign.
      i += 2
      continue
    }
    if (c === '`') {
      let ticks = 1
      while (text[i + ticks] === '`') ticks += 1
      const close = closeCode(text, i + ticks, ticks)
      if (close >= 0) {
        out.push({ kind: 'code', start: i, end: close + ticks })
        i = close + ticks
        continue
      }
      i += ticks
      continue
    }
    if (c === '$') {
      if (text[i + 1] === '$') {
        const close = closeDisplay(text, i + 2)
        if (close >= 0 && text.slice(i + 2, close).trim()) {
          out.push({ kind: 'display', start: i, end: close + 2, open: '$$', tex: text.slice(i + 2, close) })
          i = close + 2
          continue
        }
        // An empty $$ $$ is left as typed, both pairs, so its closing pair
        // does not open a formula with the next $$ in the message.
        i = close >= 0 ? close + 2 : i + 2
        continue
      }
      const close = closeInline(text, i + 1)
      if (close >= 0) {
        out.push({ kind: 'inline', start: i, end: close + 1, open: '$', tex: text.slice(i + 1, close) })
        i = close + 1
        continue
      }
    }
    i += 1
  }
  return out
}

// A formula's environments in forms KaTeX draws inside a $$ block, without
// the labels and numbering switches it refuses. A row's \tag, refused inside
// aligned, becomes its number written after the row.
export function fixEnvs(tex: string): string {
  let hasRows = false
  let out = tex.replace(
    /\\(begin|end)\{(equation|align|flalign|alignat|gather|multline|eqnarray|split)\*?\}/g,
    (_all, which: string, name: string) => {
      const to = ENV_REPLACEMENT[name] ?? ''
      if (to === '') return ''
      hasRows = true
      return which === 'begin' && to === 'array' ? '\\begin{array}{rcl}' : `\\${which}{${to}}`
    },
  )
  out = out.replace(/[ \t]*\\label\{[^{}]*\}/g, '').replace(/[ \t]*\\(?:nonumber|notag)(?![A-Za-z])/g, '')
  if (hasRows) {
    out = out.replace(/\\tag\*\{([^{}]*)\}/g, '\\qquad \\text{$1}').replace(/\\tag\{([^{}]*)\}/g, '\\qquad \\text{($1)}')
  }
  return out
}

// What comes before a formula on its line: the quote markers and the
// indent or list marker that hold it in its place, then any words. `prefix`
// is what the lines of a block written there start with, so the block stays
// in the quote or the list item.
function lineContext(before: string) {
  const m = /^((?:[ \t]*>[ \t]?)*)([ \t]*)(?:([-*+]|\d{1,9}[.)])([ \t]+))?/.exec(before)
  const quote = m?.[1] ?? ''
  const marker = m?.[3] ?? ''
  const prefix = quote + (m?.[2] ?? '') + ' '.repeat(marker ? marker.length + (m?.[4] ?? ' ').length : 0)
  return {
    quote,
    marker,
    prefix,
    words: before.slice(m?.[0].length ?? 0),
    quoteDepth: (quote.match(/>/g) ?? []).length,
  }
}

// The line around position `at`.
function lineAt(text: string, at: number): string {
  const start = text.lastIndexOf('\n', at - 1) + 1
  const end = text.indexOf('\n', at)
  return text.slice(start, end < 0 ? text.length : end)
}

const isBlank = (line: string) => /^(?:[ \t]*>)*[ \t]*$/.test(line)

// A formula's lines as a block holds them: quote markers and indents gone,
// blank lines dropped (a blank line in TeX is a paragraph break, which
// KaTeX refuses in math).
function formulaLines(tex: string, quoteDepth: number): string[] {
  return tex
    .split('\n')
    .map(line => {
      for (let d = 0; d < quoteDepth; d++) line = line.replace(/^[ \t]*>[ \t]?/, '')
      return line.replace(/^[ \t]+/, '').replace(/(?<!\\)[ \t]+$/, '')
    })
    .filter(line => line !== '')
}

// Whether a $$ formula is already a block the app draws: each $$ alone on
// its line.
function isBlock(text: string, seg: { start: number; end: number }): boolean {
  if (!/^[ \t]*\n/.test(text.slice(seg.start + 2, seg.end))) return false
  const closeLine = text.slice(text.lastIndexOf('\n', seg.end - 3) + 1, seg.end - 2)
  return isBlank(closeLine)
}

// An inline formula's body made safe for the app's tests: on one line, a
// norm's \| (which they read as a regex escape) written \Vert, and a bare %
// (which would end the formula early in KaTeX) escaped.
function repairBody(tex: string): string {
  return tex
    .replace(/[ \t]*\r?\n[ \t]*/g, ' ')
    .replace(/\\\|(?=[A-Za-z])/g, '\\Vert ')
    .replace(/\\\|/g, '\\Vert')
    .replace(/(?<!\\)%/g, '\\%')
}

// A formula of short names, joined the way the app joins one-letter names
// (F_G, Re_D, P_A - P_B, f(Re, Pr)), with a mark its tests look for and
// KaTeX draws as nothing: each subscript in braces, or {} after a formula
// with none. Null for anything else.
function markNames(body: string): string | null {
  if (!isPlain(body.replace(SHORT_NAME, 'x'))) return null
  return body.includes('_') ? body.replace(/_([A-Za-z0-9])/g, '_{$1}') : `${body}{}`
}

// How the inline formula at text[start, end) is best handed to the app:
// null to leave it as written (it draws already, or no form would draw it),
// 'display' when it is too long for any inline form, or the text to put in
// its place. $...$ comes first, with a zero-width space beside a dollar the
// neighbouring character would stop; then \(...\), with a space before it
// where the character before would stop that. The formula as written is
// tried first, then a formula of short names with its mark. A table cell's
// text starts after its bar.
function inlineForm(text: string, start: number, end: number, open: string, tex: string, inTable: boolean): string | 'display' | null {
  let before = charBefore(text, start)
  if (inTable && before === '|') before = undefined
  const after = text[end]
  const afterNext = text[end + 1]
  const repaired = repairBody(fixEnvs(tex))
  if (repaired === tex) {
    if (open === '$' && dollarDraws(tex, before, after, afterNext)) return null
    if (open === '\\(' && backslashDraws(tex, before)) return null
  }
  const body = repaired.trim()
  if (body === '') return null
  const pre = dollarOpensAfter(before) ? '' : ZERO_WIDTH_SPACE
  const post = dollarClosesBefore(after, afterNext) ? '' : ZERO_WIDTH_SPACE
  const marked = markNames(body)
  for (const form of marked === null ? [body] : [body, marked]) {
    if (dollarDraws(form, before, after, afterNext)) return `$${form}$`
    if ((pre || post) && dollarDraws(form, pre || before, post || after, afterNext)) return `${pre}$${form}$${post}`
    if (backslashDraws(form, before)) return `\\(${form}\\)`
    if (backslashDraws(form, ' ')) return ` \\(${form}\\)`
  }
  return body.length > MAX_BACKSLASH_BODY && hasTexMarks(body) ? 'display' : null
}

// Rewrites the formulas of a stretch of text with no code fences.
function rewrite(text: string): string {
  let out = ''
  let at = 0
  for (const seg of scan(text)) {
    if (seg.kind === 'code') continue
    const lineStart = text.lastIndexOf('\n', seg.start - 1) + 1
    const newline = text.indexOf('\n', seg.end)
    const lineEnd = newline < 0 ? text.length : newline
    const before = text.slice(lineStart, seg.start)
    const after = text.slice(seg.end, lineEnd)
    const line = lineContext(before)
    const opensLine = line.words.trim() === ''
    const isWhole = opensLine && after.trim() === ''
    const isOneLine = !seg.tex.includes('\n')
    const inTable = /^(?:[ \t]*>)*[ \t]*\|/.test(text.slice(lineStart, lineEnd))
    if (seg.open === '\\[' && isOneLine && !TEX_MARK.test(seg.tex) && (!isWhole || /[^\x00-\x7f]/.test(seg.tex))) continue
    // Inline formulas, $$ inside a sentence and any formula in a table cell
    // (which holds no block) go in as inline math.
    if (seg.kind === 'inline' || (isOneLine && (inTable || (seg.open === '$$' && !isWhole)))) {
      const form = inlineForm(text, seg.start, seg.end, seg.open, seg.tex, inTable)
      if (form === null || (form === 'display' && inTable)) continue
      if (form !== 'display') {
        out += text.slice(at, seg.start) + form
        at = seg.end
        continue
      }
    }
    const fixed = fixEnvs(seg.tex)
    const body = formulaLines(fixed, line.quoteDepth)
    if (body.length === 0) continue
    if (seg.open === '$$' && isWhole && fixed === seg.tex && isBlock(text, seg)) continue
    const blank = line.quote.trimEnd()
    if (opensLine) {
      // The formula opens its line, which keeps its own start, a list
      // marker included. A blank line sets it apart from a paragraph above.
      out += text.slice(at, lineStart)
      if (!line.marker && lineStart > 0 && !isBlank(lineAt(text, lineStart - 1))) out += `${blank}\n`
      out += `${before}$$`
    } else {
      out += `${text.slice(at, seg.start).replace(/[ \t]+$/, '')}\n${blank}\n${line.prefix}$$`
    }
    for (const row of body) out += `\n${line.prefix}${row}`
    out += `\n${line.prefix}$$`
    if (after.trim() !== '') {
      // The words after the formula go on below it, in the same place.
      out += `\n${blank}\n${line.prefix}`
      at = seg.end + (after.length - after.trimStart().length)
    } else {
      at = lineEnd
      if (lineEnd < text.length && !isBlank(lineAt(text, lineEnd + 1))) out += `\n${blank}`
    }
  }
  return out + text.slice(at)
}

// A text or code fence region of a message, in order. Joined with line
// breaks, the regions are the message again.
type Region = { fence: false; text: string } | { fence: true; text: string; lang: string; closed: boolean }

function splitFences(text: string): Region[] {
  const regions: Region[] = []
  let current: string[] = []
  let fence: { marker: string; lang: string } | null = null
  const pushText = () => {
    if (current.length) regions.push({ fence: false, text: current.join('\n') })
    current = []
  }
  for (const line of text.split('\n')) {
    const m = FENCE_RE.exec(line)
    const marker = m?.[2] ?? ''
    const rest = m ? line.slice(m[0].length) : ''
    if (fence === null) {
      // A backtick fence's info string holds no backtick: ```a``` is code
      // in a line, not a fence.
      if (m && !(marker[0] === '`' && rest.includes('`'))) {
        pushText()
        fence = { marker, lang: (m[3] ?? '').toLowerCase() }
      }
      current.push(line)
      continue
    }
    current.push(line)
    const closes = m && marker[0] === fence.marker[0] && marker.length >= fence.marker.length && !m[3] && rest.trim() === ''
    if (closes) {
      regions.push({ fence: true, text: current.join('\n'), lang: fence.lang, closed: true })
      current = []
      fence = null
    }
  }
  if (fence !== null) regions.push({ fence: true, text: current.join('\n'), lang: fence.lang, closed: false })
  else pushText()
  return regions
}

// The reply with every formula in a form the app draws: \[...\], a bare
// environment and a one-line $$...$$ become $$ blocks on lines of their own,
// environments KaTeX lacks become ones it has, and an inline formula the
// app's tests would refuse becomes one they take. Code, and math already
// right, are left exactly as written; a reply with nothing to change comes
// back as the same string.
export function normalize(text: string): string {
  if (!/\$|\\\(|\\\[|\\begin\{/.test(text)) return text
  const out = splitFences(text)
    .map(region => (region.fence ? region.text : rewrite(region.text)))
    .join('\n')
  return out === text ? text : out
}

// A reply holding finished ```tikz blocks, cut into its markdown and its
// figures; null when it holds none. A block still being written stays code.
export function splitFigures(text: string): Piece[] | null {
  if (!/(?:```|~~~)[ \t]*tikz/i.test(text)) return null
  const pieces: Piece[] = []
  let md: string[] = []
  let found = false
  for (const region of splitFences(text)) {
    if (region.fence && region.closed && region.lang === 'tikz') {
      if (md.length) pieces.push({ kind: 'md', text: md.join('\n') })
      md = []
      // Blank lines at either end of a block are dropped: a pasted block
      // often ends with one.
      const source = region.text.split('\n').slice(1, -1).join('\n').replace(/^(\s*\n)+|(\n\s*)+$/g, '')
      pieces.push({ kind: 'figure', source, raw: region.text })
      found = true
    } else {
      md.push(region.text)
    }
  }
  if (md.length) pieces.push({ kind: 'md', text: md.join('\n') })
  return found ? pieces : null
}

