// The desktop app's own tests for inline math, as its markdown renderer runs
// them (read from the claude.ai code the app had cached, Claude 2.42304 with
// Claude Code 2.1.299). $...$ must pass one test and \(...\) another; a
// formula that fails shows as raw source. The mod runs the same tests to
// hand the app each inline formula in a form it accepts. If the app changes
// its tests these go stale, and a formula they pass but the app refuses
// shows as source, as it would with no mod.

// TeX's marks: \(...\) needs one, and so does a $...$ that is more than
// plain arithmetic.
const TEX_MARK = /[\\^{}=<>|!+]/
// A one-letter name with a subscript: x_1, a_b, x_{.
const SUBSCRIPT = /(?<![A-Za-z0-9_])(?:[a-z]_[A-Za-z0-9]|[A-Z]_[a-z0-9])(?![A-Za-z0-9_])|(?<![A-Za-z0-9_])[A-Za-z]_\{/
const DIGIT_SUBSCRIPT = /(?<![A-Za-z0-9_])[A-Za-z]_\d(?![A-Za-z0-9_])/
const ESCAPED_PUNCTUATION = /\\[!-/:-@[-`{-~]/g
// What a formula may follow, besides any character past ASCII for $...$.
const OPENS_AFTER = new Set([' ', '\t', '\n', '(', '['])
// What a closing $ may come before, besides any character past ASCII.
const CLOSES_BEFORE = new Set(' \t\r\n.,;:!?)]*_~|-`[<')
// Emphasis marks the app looks past for the character before a formula.
const EMPHASIS = new Set(['*', '_', '~'])
const CLI_FLAG = /(^|\s)-{1,2}[A-Za-z]/
const TEX_COMMAND = /\\[a-zA-Z]|\^/
const REGEX_ESCAPE = /\\[|.+*?0-9]/
const ENDS_WITH_OPERATOR = /(?:(?<![_^])[-+*]|[=<>/^_({[,:;\\])$/
const CODE_LIKE = /[=!]~|&&|[@#"]|\\\\|(?:^|[\s(=,])'|[\s'"(/[=,;]\^(?!\{)|(?:^|[\s({|&])!$/
const MARKUP = /\*\*|__|~~|\]\(|<\/?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*)?\/?>|<[!?]/
const ATOM = String.raw`-?(?:\d+(?:[.,]\d+)*[a-z]{0,2}|[a-z])[!']*`
const JOIN = String.raw`(?: ?[-+*/:] ?|, )`
const TERM = `(?:${ATOM}|\\(${ATOM}(?:${JOIN}${ATOM})*\\))`
// Plain arithmetic, or a list of numbers and one-letter names: a+b, (x, y).
const PLAIN = new RegExp(`^${TERM}(?:(?:${JOIN}|(?=\\())${TERM})*$`, 'i')
// Words outside braces: four letters that are no command's, two CJK or
// Hangul letters, or a bare %.
const WORDS = /(?<![\\\p{L}])\p{L}{4}|[\p{scx=Han}\p{scx=Hiragana}\p{scx=Katakana}\p{scx=Hangul}]{2}|(?<!\\)%/u

// The longest body each form takes, in UTF-16 units.
export const MAX_DOLLAR_BODY = 60
export const MAX_BACKSLASH_BODY = 200

const isWide = (ch: string) => ch > '\x7f'

// The character a formula opening at `at` follows, past emphasis marks;
// undefined at the start of the text.
export function charBefore(text: string, at: number): string | undefined {
  let n = at - 1
  const limit = at - 65
  while (n >= 0 && EMPHASIS.has(text[n] ?? '')) {
    if (n <= limit) return text[n]
    n--
  }
  return n >= 0 ? text[n] : undefined
}

// Whether a $ may open after `before`.
export function dollarOpensAfter(before: string | undefined): boolean {
  return before === undefined || OPENS_AFTER.has(before) || isWide(before)
}

// Whether a closing $ may come before `after` (and the one after it).
export function dollarClosesBefore(after: string | undefined, afterNext?: string): boolean {
  if (after === '\\') return afterNext === undefined || afterNext === '\n' || afterNext === '\r'
  return after === undefined || CLOSES_BEFORE.has(after) || isWide(after)
}

// What neither form takes: a dollar, a backtick, a \( or a regex escape
// such as \| in the body.
function refusedByBoth(body: string): boolean {
  return body.includes('$') || body.includes('`') || body.includes('\\(') || REGEX_ESCAPE.test(body)
}

// Whether the body outside braces reads as words: prose between two dollars.
function readsAsWords(body: string): boolean {
  let depth = 0
  let out = ''
  for (let i = 0; i < body.length; i++) {
    const ch = body[i]
    if (ch === '\\') {
      out += depth === 0 ? body.slice(i, i + 2) : '  '
      i++
      continue
    }
    if (ch === '{') depth++
    else if (ch === '}' && depth > 0) depth--
    else if (depth === 0) {
      out += ch
      continue
    }
    out += ' '
  }
  return WORDS.test(out)
}

// Whether a body is plain arithmetic, which the app takes with no mark of
// TeX: one letter, or numbers and one-letter names joined as in a+b or
// (x, y), not opening with a digit.
export function isPlain(body: string): boolean {
  return body.length === 1 ? /[A-Za-z]/.test(body) : !/^\d/.test(body) && PLAIN.test(body)
}

function isUnbalanced(body: string): boolean {
  let round = 0
  let curly = 0
  let bars = 0
  for (let i = 0; i < body.length; i++) {
    const ch = body[i]
    if (ch === '\\') i++
    else if (ch === '(' || ch === '[') round++
    else if ((ch === ')' || ch === ']') && --round < 0) return true
    else if (ch === '{') curly++
    else if (ch === '}' && --curly < 0) return true
    else if (ch === '|') bars++
  }
  return round !== 0 || curly !== 0 || (bars % 2 === 1 && body.endsWith('|'))
}

// Whether the app draws $body$ between `before` and `after`, the characters
// around the dollars (undefined at either end of the text).
export function dollarDraws(body: string, before: string | undefined, after: string | undefined, afterNext?: string): boolean {
  if (!dollarOpensAfter(before) || !dollarClosesBefore(after, afterNext)) return false
  if (body === '' || body.length > MAX_DOLLAR_BODY || /^\s|\s$/.test(body)) return false
  if (refusedByBoth(body) || ENDS_WITH_OPERATOR.test(body) || CODE_LIKE.test(body) || MARKUP.test(body) || isUnbalanced(body)) return false
  const plain = isPlain(body)
  if (body[0] === '{' || (body[0] === '(' && !plain && !TEX_COMMAND.test(body))) return false
  return plain || ((TEX_MARK.test(body) || SUBSCRIPT.test(body)) && /[A-Za-z0-9\\]/.test(body) && !readsAsWords(body))
}

// Whether a body has what \(...\) needs, at any length: a mark of TeX, and
// nothing that reads as code.
export function hasTexMarks(body: string): boolean {
  if (refusedByBoth(body) || (CLI_FLAG.test(body) && !TEX_COMMAND.test(body))) return false
  const marks = body.includes('\\') ? body.replace(ESCAPED_PUNCTUATION, ' ') : body
  return TEX_MARK.test(marks) || DIGIT_SUBSCRIPT.test(marks)
}

// Whether the app draws \(body\) after `before`.
export function backslashDraws(body: string, before: string | undefined): boolean {
  if (before !== undefined && !OPENS_AFTER.has(before)) return false
  return body.length <= MAX_BACKSLASH_BODY && hasTexMarks(body)
}

